messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: #00ffcc;
            font-family: monospace;
            pointer-events: none;
            text-shadow: 0 0 5px #00ffcc;
        }
    </style>
</head>
<body>
    <div id="info">State: <span id="status" style="color:white">STANDING</span></div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(12, 8, 12); // Side-on view
        camera.lookAt(0, 2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(-10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment (Treadmill) ---
        const groundGeo = new THREE.PlaneGeometry(40, 40);
        const groundMat = new THREE.MeshStandardMaterial({ 
            color: 0x444444, 
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Add treadmill belt lines
        const lineMat = new THREE.MeshBasicMaterial({ color: 0x00ffcc });
        const lineGeo = new THREE.PlaneGeometry(40, 0.2);
        const belt = new THREE.Mesh(lineGeo, lineMat);
        belt.rotation.x = -Math.PI / 2;
        belt.position.y = 0.02;
        scene.add(belt);

        // --- Humanoid Construction ---
        const humanGroup = new THREE.Group();
        scene.add(humanGroup);

        const material = new THREE.MeshStandardMaterial({ color: 0x0088ff, flatShading: true });
        const darkMat = new THREE.MeshStandardMaterial({ color: 0x0055aa, flatShading: true });

        // Helper to create limbs
        function createLimb(length, width, height, x, y, z, rx, ry, rz, joints) {
            const group = new THREE.Group();
            group.position.set(x, y, z);
            group.rotation.set(rx, ry, rz);

            const geo = new THREE.BoxGeometry(length, width, height);
            const mesh = new THREE.Mesh(geo, material);
            mesh.position.y = height / 2; // Pivot at bottom
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            group.add(mesh);

            // Joints (shoulder/hip)
            const jointGeo = new THREE.BoxGeometry(width * 1.5, width * 1.5, height * 1.5);
            const joint = new THREE.Mesh(jointGeo, darkMat);
            joint.position.y = -height / 2;
            group.add(joint);

            if (joints) group.userData.joint = joint;
            return group;
        }

        // Torso
        const torsoGeo = new THREE.BoxGeometry(1.2, 2.5, 0.8);
        const torso = new THREE.Mesh(torsoGeo, material);
        torso.position.y = 2.5;
        torso.castShadow = true;
        humanGroup.add(torso);

        // Head
        const headGeo = new THREE.BoxGeometry(0.8, 0.9, 0.9);
        const head = new THREE.Mesh(headGeo, material);
        head.position.set(0, 3.8, 0);
        head.castShadow = true;
        humanGroup.add(head);

        // Arms
        // Left Arm
        const leftArm = createLimb(1.4, 0.3, 0.3, -0.8, 2.0, 0, 0, 0, [0,0,0], true);
        humanGroup.add(leftArm);
        // Right Arm
        const rightArm = createLimb(1.4, 0.3, 0.3, 0.8, 2.0, 0, 0, 0, [0,0,0], true);
        humanGroup.add(rightArm);

        // Legs
        // Left Leg
        const leftLeg = createLimb(1.6, 0.4, 0.4, -0.4, 1.0, 0, 0, 0, [0,0,0], true);
        humanGroup.add(leftLeg);
        // Right Leg
        const rightLeg = createLimb(1.6, 0.4, 0.4, 0.4, 1.0, 0, 0, 0, [0,0,0], true);
        humanGroup.add(rightLeg);

        // --- Animation Logic ---
        let startTime = performance.now();
        let cyclePercent = 0; // 0 to 1
        let state = 'STANDING'; // STANDING, WALKING, RUNNING

        // Animation State Objects
        const limbs = {
            leftArm: leftArm,
            rightArm: rightArm,
            leftLeg: leftLeg,
            rightLeg: rightLeg
        };

        // Helper to get rotation
        const getRot = (obj) => {
            return { x: obj.rotation.x, y: obj.rotation.y, z: obj.rotation.z };
        };

        const setRot = (obj, rot) => {
            obj.rotation.set(rot.x, rot.y, rot.z);
        };

        // Current offsets
        let armOffsetX = 0;
        let legOffsetX = 0;
        let leanAngle = 0;

        function animate() {
            const now = performance.now();
            const elapsed = (now - startTime) / 1000; // seconds

            // Cycle: 2s Stand, 3s Walk, 3s Run, 2s Stand = 10s
            // Phase 0: 0-2s (Stand)
            // Phase 1: 2-5s (Walk)
            // Phase 2: 5-8s (Run)
            // Phase 3: 8-10s (Stand)

            // Calculate progress within the 10s cycle
            let cycleIndex = Math.floor(elapsed % 10);

            if (cycleIndex < 2) {
                state = 'STANDING';
                document.getElementById('status').innerText = "STANDING";
                document.getElementById('status').style.color = "#ffffff";
            } else if (cycleIndex < 5) {
                state = 'WALKING';
                document.getElementById('status').innerText = "WALKING";
                document.getElementById('status').style.color = "#ffff00";
            } else if (cycleIndex < 8) {
                state = 'RUNNING';
                document.getElementById('status').innerText = "RUNNING";
                document.getElementById('status').style.color = "#ff0055";
            } else {
                state = 'STANDING';
                document.getElementById('status').innerText = "STANDING";
                document.getElementById('status').style.color = "#ffffff";
            }

            // Reset offsets on state change to prevent drift
            if (state !== 'STANDING' && (Math.floor(elapsed) !== Math.floor(startTime/1000))) {
                 // This logic is tricky with simple time checks, so we just use the cycle index math
            }

            // Smooth transition of offsets
            let walkProgress = (cycleIndex - 2) / 3; // 0 to 1
            let runProgress = (cycleIndex - 5) / 3; // 0 to 1

            // Calculate target offsets based on state
            let targetArmX = 0, targetLegX = 0, targetLean = 0;

            if (state === 'STANDING') {
                targetArmX = 0;
                targetLegX = 0;
                targetLean = 0;
            } else if (state === 'WALKING') {
                // 0.5 swing amplitude
                targetArmX = Math.sin(walkProgress * Math.PI * 2) * 0.5;
                targetLegX = -Math.sin(walkProgress * Math.PI * 2) * 0.5; // Opposite phase
                targetLean = 0;
            } else if (state === 'RUNNING') {
                // 1.2 swing amplitude (larger)
                targetArmX = Math.sin(runProgress * Math.PI * 2) * 1.2;
                targetLegX = -Math.sin(runProgress * Math.PI * 2) * 1.2;
                // Forward lean
                targetLean = Math.sin(runProgress * Math.PI * 2) * 0.2; 
            }

            // Linear interpolation for smoothness
            armOffsetX += (targetArmX - armOffsetX) * 0.1;
            legOffsetX += (targetLegX - legOffsetX) * 0.1;
            leanAngle += (targetLean - leanAngle) * 0.1;

            // --- Apply Animation ---

            // Torso Lean
            humanGroup.rotation.z = leanAngle;

            // Arms
            // Rotate the entire arm group (includes shoulder joint)
            limbs.leftArm.rotation.x = armOffsetX;
            limbs.rightArm.rotation.x = armOffsetX;

            // Hands (add a slight twist for natural look)
            limbs.leftArm.children[0].rotation.z = armOffsetX * 0.5; // Hand rotates slightly
            limbs.rightArm.children[0].rotation.z = armOffsetX * 0.5;

            // Legs
            // Rotate the entire leg group
            limbs.leftLeg.rotation.x = legOffsetX;
            limbs.rightLeg.rotation.x = legOffsetX;

            // Knees (add a slight bend for realism, especially running)
            // We modify the rotation of the child mesh (the actual leg cylinder) relative to the group
            // Actually, in our structure, the leg group is the pivot. The child mesh is the leg.
            // So rotating the group moves the whole leg.
            // To bend the knee, we need to rotate the child mesh around X.

            // Simple knee bend logic:
            // If leg is rotating forward (positive X), knee might bend slightly back.
            // Let's just rotate the mesh inside the leg group.
            let kneeBend = 0;
            if (state === 'RUNNING') kneeBend = Math.sin(runProgress * Math.PI * 2) * 0.15;

            limbs.leftLeg.children[0].rotation.x = kneeBend;
            limbs.rightLeg.children[0].rotation.x = kneeBend;

            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();
    </script>
</body>
</html>
```
